export const STROKE_CROSSBAR_T = [[[454.795, 139.713], [505.645, 140.481], [587.659, 133.973], [624.462, 134.38]]];
export const STROKE_CROSSBAR_H = [[[817.187, 128.713], [820.105, 127.984], [939.259, 119.573], [968.854, 118.713]]];

// Metaphonyパスの元座標系(SVGのviewBox)。他モジュールから座標変換する際の基準値として利用する。
export const METAPHONY_VIEWBOX = { width: 1352, height: 409 };
// おおよそのベースラインY座標(この値を中心に、上下反転してワールド座標へ写す際の基準にする)
export const METAPHONY_BASELINE_Y = 226;

// 書き順どおりに並べたストローク列。reveal(t) はこの順に、弧長に比例した
// 時間配分で伸びていく。
const STROKE_SEQUENCE = [
  { segments: STROKE_MAIN, kind: 'main' },
  { segments: STROKE_CROSSBAR_T, kind: 'cross' },
  { segments: STROKE_CROSSBAR_H, kind: 'cross' },
];

export function segmentsToCurvePath(segments) {
  const curvePath = new THREE.CurvePath();
  for (const [p0, p1, p2, p3] of segments) {
    curvePath.add(new THREE.CubicBezierCurve3(
      new THREE.Vector3(p0[0], p0[1], 0),
      new THREE.Vector3(p1[0], p1[1], 0),
      new THREE.Vector3(p2[0], p2[1], 0),
      new THREE.Vector3(p3[0], p3[1], 0),
    ));
  }
  return curvePath;
}

const SAMPLES_PER_UNIT_LENGTH = 0.6; // 弧長1あたりのサンプル点数(密度)

export function createMetaphonyPath(scene, { color = 0x111111, lineWidth = 2 } = {}) {
  // 各ストロークを弧長で等間隔サンプリングし、弧長に比例したサンプル数を割り当てる
  const groups = STROKE_SEQUENCE.map(({ segments, kind }) => {
    const curvePath = segmentsToCurvePath(segments);
    const length = curvePath.getLength();
    const sampleCount = Math.max(2, Math.round(length * SAMPLES_PER_UNIT_LENGTH));
    const points = curvePath.getSpacedPoints(sampleCount);
    return { points, length, kind };
  });

  const totalLength = groups.reduce((sum, g) => sum + g.length, 0);
  const totalSamples = groups.reduce((sum, g) => sum + g.points.length, 0);

  const positions = new Float32Array(totalSamples * 3);
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
  geometry.setDrawRange(0, 0);

  const material = new THREE.LineBasicMaterial({ color, linewidth: lineWidth, transparent: true, opacity: 1 });
  const line = new THREE.Line(geometry, material);
  line.frustumCulled = false;
  line.visible = false;
  scene.add(line);

  // 全点をあらかじめpositionsへ書き込み、drawRangeだけを動かして「伸びていく」演出にする
  let idx = 0;
  const groupOffsets = []; // 各グループの [開始インデックス, 点数, 累積弧長の開始比率, 弧長比率]
  let cumLength = 0;
  for (const g of groups) {
    const startIdx = idx / 3;
    for (const p of g.points) {
      positions[idx++] = p.x; positions[idx++] = p.y; positions[idx++] = p.z;
    }
    groupOffsets.push({
      startIdx,
      count: g.points.length,
      lengthStart: cumLength / totalLength,
      lengthRatio: g.length / totalLength,
    });
    cumLength += g.length;
  }
  geometry.attributes.position.needsUpdate = true;

  // reveal(t): 弧長ベースで t=0→1 を書き順どおりに伸ばす。
  // (M,e,t,a,p,h,o,n,y → tの横線 → hの横線 の順で、弧長に比例した速さで進む)
  function reveal(t) {
    const clamped = THREE.MathUtils.clamp(t, 0, 1);
    line.visible = clamped > 0;

    let totalVisibleCount = 0;
    for (const g of groupOffsets) {
      const localT = (clamped - g.lengthStart) / g.lengthRatio;
      if (localT <= 0) {
        continue; // このグループはまだ始まっていない
      } else if (localT >= 1) {
        totalVisibleCount = g.startIdx + g.count; // このグループは全部見える
      } else {
        const visibleInGroup = Math.floor(localT * g.count);
        totalVisibleCount = g.startIdx + visibleInGroup;
        break; // 現在進行中のグループより先は見せない
      }
    }
    geometry.setDrawRange(0, totalVisibleCount);
  }

  function reset() {
    geometry.setDrawRange(0, 0);
    line.visible = false;
  }

  return { line, reveal, reset, groups };
}
